const upsertCampaign = `-- name: UpsertCampaign :one
INSERT INTO campaigns (
    kind,
    simhash,
    normalized_text,
    first_seen,
    last_seen,
    comment_count,
    commenter_count,
    video_count,
    evidence
) VALUES (
    $1,
    $2,
    COALESCE($3, ''),
    COALESCE($4, NOW()),
    COALESCE($5, NOW()),
    COALESCE($6, 0),
    COALESCE($7, 0),
    COALESCE($8, 0),
    COALESCE($9::jsonb, '{}'::jsonb)
)
ON CONFLICT (simhash)
WHERE kind = 'copypaste' AND simhash IS NOT NULL
DO UPDATE SET
    normalized_text = CASE
        WHEN EXCLUDED.normalized_text <> '' THEN EXCLUDED.normalized_text
        ELSE campaigns.normalized_text
    END,
    first_seen = LEAST(campaigns.first_seen, EXCLUDED.first_seen),
    last_seen = GREATEST(campaigns.last_seen, EXCLUDED.last_seen),
    comment_count = GREATEST(campaigns.comment_count, EXCLUDED.comment_count),
    commenter_count = GREATEST(campaigns.commenter_count, EXCLUDED.commenter_count),
    video_count = GREATEST(campaigns.video_count, EXCLUDED.video_count),
    evidence = EXCLUDED.evidence,
    updated_at = NOW()
RETURNING id, kind, simhash, normalized_text, first_seen, last_seen, comment_count, commenter_count, video_count, evidence, created_at, updated_at
`

type UpsertCampaignParams struct {
	Kind           string      `db:"kind" json:"Kind"`
	Simhash        *int64      `db:"simhash" json:"Simhash"`
	NormalizedText interface{} `db:"normalized_text" json:"NormalizedText"`
	FirstSeen      interface{} `db:"first_seen" json:"FirstSeen"`
	LastSeen       interface{} `db:"last_seen" json:"LastSeen"`
	CommentCount   interface{} `db:"comment_count" json:"CommentCount"`
	CommenterCount interface{} `db:"commenter_count" json:"CommenterCount"`
	VideoCount     interface{} `db:"video_count" json:"VideoCount"`
	Evidence       []byte      `db:"evidence" json:"Evidence"`
}

// UpsertCampaign
//
//	INSERT INTO campaigns (
//	    kind,
//	    simhash,
//	    normalized_text,
//	    first_seen,
//	    last_seen,
//	    comment_count,
//	    commenter_count,
//	    video_count,
//	    evidence
//	) VALUES (
//	    $1,
//	    $2,
//	    COALESCE($3, ''),
//	    COALESCE($4, NOW()),
//	    COALESCE($5, NOW()),
//	    COALESCE($6, 0),
//	    COALESCE($7, 0),
//	    COALESCE($8, 0),
//	    COALESCE($9::jsonb, '{}'::jsonb)
//	)
//	ON CONFLICT (simhash)
//	WHERE kind = 'copypaste' AND simhash IS NOT NULL
//	DO UPDATE SET
//	    normalized_text = CASE
//	        WHEN EXCLUDED.normalized_text <> '' THEN EXCLUDED.normalized_text
//	        ELSE campaigns.normalized_text
//	    END,
//	    first_seen = LEAST(campaigns.first_seen, EXCLUDED.first_seen),
//	    last_seen = GREATEST(campaigns.last_seen, EXCLUDED.last_seen),
//	    comment_count = GREATEST(campaigns.comment_count, EXCLUDED.comment_count),
//	    commenter_count = GREATEST(campaigns.commenter_count, EXCLUDED.commenter_count),
//	    video_count = GREATEST(campaigns.video_count, EXCLUDED.video_count),
//	    evidence = EXCLUDED.evidence,
//	    updated_at = NOW()
//	RETURNING id, kind, simhash, normalized_text, first_seen, last_seen, comment_count, commenter_count, video_count, evidence, created_at, updated_at
func (q *Queries) UpsertCampaign(ctx context.Context, arg *UpsertCampaignParams) (*Campaign, error) {
	row := q.db.QueryRow(ctx, upsertCampaign,
		arg.Kind,
		arg.Simhash,
		arg.NormalizedText,
		arg.FirstSeen,
		arg.LastSeen,
		arg.CommentCount,
		arg.CommenterCount,
		arg.VideoCount,
		arg.Evidence,
	)
	var i Campaign
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.Simhash,
		&i.NormalizedText,
		&i.FirstSeen,
		&i.LastSeen,
		&i.CommentCount,
		&i.CommenterCount,
		&i.VideoCount,
		&i.Evidence,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return &i, err
}

