const upsertOsintFlag = `-- name: UpsertOsintFlag :one
INSERT INTO osint_flags (kind, commenter_id, video_id, campaign_id, score, evidence, natural_key)
VALUES (
    $1,
    $2,
    $3,
    $4,
    COALESCE($5, 0),
    COALESCE($6::jsonb, '{}'::jsonb),
    $7
)
ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL
DO UPDATE SET
    score = EXCLUDED.score,
    evidence = EXCLUDED.evidence
RETURNING id, kind, commenter_id, video_id, campaign_id, score, evidence, created_at, dismissed_at, dismissed_by, natural_key
`

type UpsertOsintFlagParams struct {
	Kind        string      `db:"kind" json:"Kind"`
	CommenterID pgtype.UUID `db:"commenter_id" json:"CommenterID"`
	VideoID     pgtype.UUID `db:"video_id" json:"VideoID"`
	CampaignID  pgtype.UUID `db:"campaign_id" json:"CampaignID"`
	Score       interface{} `db:"score" json:"Score"`
	Evidence    []byte      `db:"evidence" json:"Evidence"`
	NaturalKey  *string     `db:"natural_key" json:"NaturalKey"`
}

// UpsertOsintFlag
//
//	INSERT INTO osint_flags (kind, commenter_id, video_id, campaign_id, score, evidence, natural_key)
//	VALUES (
//	    $1,
//	    $2,
//	    $3,
//	    $4,
//	    COALESCE($5, 0),
//	    COALESCE($6::jsonb, '{}'::jsonb),
//	    $7
//	)
//	ON CONFLICT (natural_key) WHERE natural_key IS NOT NULL
//	DO UPDATE SET
//	    score = EXCLUDED.score,
//	    evidence = EXCLUDED.evidence
//	RETURNING id, kind, commenter_id, video_id, campaign_id, score, evidence, created_at, dismissed_at, dismissed_by, natural_key
func (q *Queries) UpsertOsintFlag(ctx context.Context, arg *UpsertOsintFlagParams) (*OsintFlag, error) {
	row := q.db.QueryRow(ctx, upsertOsintFlag,
		arg.Kind,
		arg.CommenterID,
		arg.VideoID,
		arg.CampaignID,
		arg.Score,
		arg.Evidence,
		arg.NaturalKey,
	)
	var i OsintFlag
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.CommenterID,
		&i.VideoID,
		&i.CampaignID,
		&i.Score,
		&i.Evidence,
		&i.CreatedAt,
		&i.DismissedAt,
		&i.DismissedBy,
		&i.NaturalKey,
	)
	return &i, err
}

